let chatId = 'ĐIỀN_CHAT_ID_CỦA_BẠN_VÀO_ĐÂY';
let isAuto = true;

try {
  const msg = $('Execute Workflow Trigger').item.json.message;
  if (msg && msg.chat && msg.chat.id) {
    chatId = msg.chat.id;
    isAuto = false;
  }
} catch(e) {}

return [{ json: { chatId: chatId, isAuto: isAuto } }];

const source = $('Chuẩn bị ChatID').item.json || {};
const data = $json || {};
const chatId = source.chatId || '';

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const formatPrice = (value) => {
  const amount = Number(value || 0);
  if (!Number.isFinite(amount) || amount <= 0) return 'N/A';
  return `${amount.toLocaleString('vi-VN')} đ/lượng`;
};

const formatChange = (value) => {
  const amount = Number(value || 0);
  if (!Number.isFinite(amount) || amount === 0) return '0 đ';
  const sign = amount > 0 ? '+' : '-';
  return `${sign}${Math.abs(amount).toLocaleString('vi-VN')} đ`;
};

let text = '⚠️ Không lấy được giá vàng lúc này. Bạn thử lại sau nhé.';

if (data.success) {
  const title = data.name || 'SJC 9999';
  const dateLine = [data.date, data.time].filter(Boolean).join(' ');

  text = `🥇 <b>Giá vàng ${escapeHtml(title)}</b>\n`;
  if (dateLine) text += `<i>${escapeHtml(dateLine)}</i>\n\n`;
  text += `🛒 <b>Mua vào:</b> ${escapeHtml(formatPrice(data.buy))}\n`;
  text += `💰 <b>Bán ra:</b> ${escapeHtml(formatPrice(data.sell))}\n`;
  text += `📉 <b>Biến động mua:</b> ${escapeHtml(formatChange(data.change_buy))}\n`;
  text += `📈 <b>Biến động bán:</b> ${escapeHtml(formatChange(data.change_sell))}`;
}

return [{ json: { chatId, text: text.trim() } }];
